                            const sorted = arr
                                .filter((v) => Number.isFinite(v) && v >= 0)
                                .sort((a, b) => a - b);
                            if (sorted.length === 0) return 0;
                            const qq = Math.max(0, Math.min(1, Number(q) || 0));
