                    objectIndex: Number.isFinite(objectIndex) ? objectIndex : 0,
                    maxFrequencyLpmm: Number.isFinite(maxFreq) ? maxFreq : 100,
                    samplingSize: Number.isFinite(sampling) ? sampling : 256,
                    zeroPadTo,
